/**
 * "What is happening": a short, rule-based selection of recent developments from official data. Nothing here is
 * editorial judgment of importance, and nothing is generated by a language model: each item is a template filled
 * from an official record, linked to explicit, hand-verified briefings only where a real connection exists.
 */
import type { GovAction } from "./gov-actions.ts";
import type { TreasuryData } from "./briefings.ts";

export type Development = {
  id: string;
  kind: "Spending and debt" | "New law" | "Presidential action" | "Open for comment" | "Final rule";
  date: string;
  headline: string;
  fact: string;
  /** Where to understand it in context. */
  understand: { label: string; href: string };
  /** The original official record. */
  original: { label: string; url: string };
  /** Why this item was chosen, shown to readers. */
  rule: string;
};

const money = (n: number) => `$${(n / 1e12).toFixed(2)} trillion`;
const fmtDay = (iso: string) => new Date(iso + "T12:00:00Z").toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" });

export function selectDevelopments(actions: GovAction[], t: TreasuryData, today: string): Development[] {
  const out: Development[] = [];
  const m = [...t.debtMilestones].sort((a, b) => b.trillions - a.trillions)[0];
  if (m)
    out.push({
      id: `debt-${m.trillions}`,
      kind: "Spending and debt",
      date: m.firstDate,
      headline: `Total federal debt first reached $${m.trillions} trillion`,
      fact: `Treasury's daily record shows total public debt outstanding at ${money(m.total)} on ${fmtDay(m.firstDate)}, the first day at or above $${m.trillions} trillion.`,
      understand: { label: "How much does the federal government spend, collect and borrow?", href: "/issues/federal-spending" },
      original: { label: "Treasury: Debt to the Penny", url: "https://fiscaldata.treasury.gov/datasets/debt-to-the-penny/debt-to-the-penny" },
      rule: "Latest trillion-dollar milestone in Treasury's daily debt series.",
    });
  const fy = t.fiscalYears[t.fiscalYears.length - 1];
  out.push({
    id: `deficit-fy${fy.fy}`,
    kind: "Spending and debt",
    date: fy.recordDate,
    headline: `Fiscal year ${fy.fy} ended with a deficit of about ${money(fy.outlays - fy.receipts)}`,
    fact: `The federal government collected about ${money(fy.receipts)} and spent about ${money(fy.outlays)} in the year ending ${fmtDay(fy.recordDate)}, according to Treasury's September statement.`,
    understand: { label: "See the numbers and what they do and don't show", href: "/issues/federal-spending" },
    original: { label: "Treasury: Monthly Treasury Statement", url: "https://fiscaldata.treasury.gov/datasets/monthly-treasury-statement/summary-of-receipts-and-outlays-of-the-u-s-government" },
    rule: "Most recent completed fiscal year in Treasury's Monthly Treasury Statement.",
  });
  const sorted = [...actions].sort((a, b) => b.date.localeCompare(a.date));
  const law = sorted.find((a) => a.kind === "law");
  if (law)
    out.push({ id: `law-${law.id}`, kind: "New law", date: law.date, headline: `${law.title} became law`, fact: law.detail, understand: { label: "Read the bill, its sponsors and timeline", href: law.href }, original: { label: "Congress.gov", url: law.sourceUrl }, rule: "Most recently enacted law in the Congress snapshot." });
  const eo = sorted.find((a) => a.kind === "executive-order");
  if (eo)
    out.push({ id: `eo-${eo.id}`, kind: "Presidential action", date: eo.date, headline: eo.title, fact: eo.detail, understand: { label: "Read the document and what an executive order can and cannot do", href: eo.href }, original: { label: "Federal Register", url: eo.sourceUrl }, rule: "Most recent executive order in the Federal Register snapshot." });
  const open = sorted.filter((a) => a.kind === "proposed-rule" && a.commentsCloseOn && a.commentsCloseOn >= today).sort((a, b) => a.commentsCloseOn!.localeCompare(b.commentsCloseOn!))[0];
  if (open)
    out.push({ id: `comment-${open.id}`, kind: "Open for comment", date: open.date, headline: open.title, fact: `${open.agency ?? "An agency"} proposed this rule. ${open.detail}`, understand: { label: "What a proposed rule is, and how comment periods work", href: open.href }, original: { label: "Federal Register", url: open.sourceUrl }, rule: "Open proposed rule whose public comment period closes soonest." });
  return out;
}
